/**
 * Types for the LinkedIn archive (/linkedin). The data is generated by
 * scripts/linkedin/build-linkedin-archive.mjs; the topic tree lives in
 * linkedinTaxonomy.json (L1 areas, L2 topics, L3 subtopics).
 */

export type LiKind = "image" | "video" | "document";
export type LiContext = "post" | "article" | "comment" | "profile";

export interface LiItem {
  /** Stable 4-digit id from the LinkedIn rich-media export, oldest first. */
  idx: string;
  kind: LiKind;
  /** Upload day, YYYY-MM-DD. */
  date: string;
  /** LinkedIn's own label, e.g. "post photo", "article cover photo". */
  label: string;
  context: LiContext;
  format: string;
  /** L2 topic ids (main first): its post's or article's topics, or its own when it stands alone. */
  topics: string[];
  /** L3 subtopic ids. */
  subtopics: string[];
  entities: string[];
  /** One plain sentence describing what the media shows. */
  description: string;
  width: number;
  height: number;
  /** Seconds, videos only. */
  duration?: number;
  /** "pdf" or "pptx", documents only. */
  docExt?: string;
  /** The article or post this media belongs to (LiPost id), when known. */
  post?: string;
  /** The media was attached to my comment on that post, not to the post itself. */
  inComment?: boolean;
  /** Present only in local previews: the item is waiting for the owner's review and must never ship. */
  review?: boolean;
}

export type LiPostType = "article" | "post";

/** Engagement as LinkedIn reported it on a given day (LinkedIn's data export has none; it comes from post analytics). */
export interface LiEngagement {
  reactions?: number;
  comments?: number;
  reposts?: number;
  impressions?: number;
  /** LinkedIn's own total of interactions (reactions, comments, reposts, clicks), from post analytics. */
  engagements?: number;
  /** The impressions figure is a floor (summed from monthly top-post lists), not LinkedIn's exact total. */
  impressionsAtLeast?: boolean;
  /** The engagements figure is a floor, as above. */
  engagementsAtLeast?: boolean;
  /** Day the numbers were read, YYYY-MM-DD. */
  asOf: string;
  /** Where the numbers came from: a key of ENGAGEMENT_SOURCES (src/data/linkedinArchive.ts) or plain text. */
  source: string;
}

/** Someone the text links to on LinkedIn (named publicly by Venkata in the post or article). */
export interface LiPerson {
  name: string;
  url: string;
}

/** A LinkedIn article or post (server-side record). Bodies live in linkedinPostBodiesData.ts. */
export interface LiPost {
  /** URL slug on this site (/linkedin/articles/<id> or /linkedin/posts/<id>). FROZEN once live. */
  id: string;
  /** Posts: LinkedIn's activity id (the post's permanent id; its slug is frozen against it in scripts/linkedin/post-slugs.json). */
  activityId?: string;
  type: LiPostType;
  title: string;
  /** LinkedIn newsletter the article belongs to, and its edition number. */
  series?: string;
  edition?: number;
  /** Published, ISO 8601 UTC. */
  date: string;
  /** The original on LinkedIn. */
  url: string;
  /** Cover image (LiItem idx). */
  cover?: string;
  /** Every public media item in it (LiItem idx), in reading order. */
  media: string[];
  /** Images I attached to my own comments on it (LiItem idx). */
  commentMedia?: string[];
  people: LiPerson[];
  /** L2 topic ids, main first. */
  topics: string[];
  /** L3 subtopic ids. */
  subtopics: string[];
  words: number;
  excerpt: string;
  engagement?: LiEngagement;
  /** Local previews only: an unpublished draft; must never ship. */
  review?: boolean;
}

/** One node of the topic tree (linkedinTaxonomy.json). */
export interface LiTopicNode {
  id: string;
  level: 1 | 2 | 3;
  parent: string | null;
  label: string;
  /** URL slug (/linkedin/topics/<slug>). FROZEN once live. */
  slug: string;
  description: string;
}

/** What the archive lists and the graph draws: a post, an article, or a media item that is in no post. */
export type LiEntryKind = "post" | "article" | "media";

/**
 * Where an entry comes from. Today every entry is from LinkedIn; the archive is built to take the others (each new
 * source shows up in the Source filter as soon as its entries exist).
 */
export type LiSource = "linkedin" | "website" | "substack" | "youtube" | "instagram" | "facebook" | "podcast" | "book";

export interface LiEntry {
  /** "post:<slug>", "article:<slug>" or "media:<idx>". */
  key: string;
  kind: LiEntryKind;
  /** Where it was published. */
  source: LiSource;
  /** Post or article slug, or media idx. */
  id: string;
  title: string;
  /** ISO time for posts and articles, YYYY-MM-DD for media. */
  date: string;
  excerpt: string;
  /** Media in it (LiItem idx); a media entry holds its own idx. */
  media: string[];
  commentMedia?: string[];
  /** The original on LinkedIn ("" for media on its own). */
  url: string;
  activityId?: string;
  engagement?: LiEngagement;
  /** L2 topic ids, main first. */
  topics: string[];
  /** L3 subtopic ids. */
  subtopics: string[];
  /** Recurring names (events, companies, products, people) seen in its media. */
  names: string[];
  words?: number;
  review?: boolean;
}

/**
 * The browser's compact entry (linkedinEntriesData.ts), expanded to LiEntry by linkedinArchive.ts:
 * k kind, i id, t title, d date, x excerpt, m media, cm comment media, a activity id, u url (articles),
 * e engagement [reactions, comments, reposts, impressions, engagements, flags: a analytics, f impressions floor,
 * g engagements floor], l2/l3 topics, n names, w words, rv review, src source (absent: LinkedIn).
 */
export interface LiEntryRaw {
  k: LiEntryKind;
  i: string;
  t: string;
  d: string;
  x: string;
  m?: string[];
  cm?: string[];
  a?: string;
  u?: string;
  e?: [number | null, number | null, number | null, number | null, number | null, string];
  l2: string[];
  l3?: string[];
  n?: string[];
  w?: number;
  rv?: 1;
  /** Source; absent means LinkedIn. */
  src?: LiSource;
}

export type LiNodeType = "topic" | "entity" | "entry";

/** The three graph views (layouts computed at build time). */
export type LiView = "topics" | "timeline" | "map";
export const LI_VIEWS: LiView[] = ["topics", "timeline", "map"];

export interface LiGraphNode {
  /** "t:<topic id>", "n:<name slug>" or "e:<entry key>". */
  id: string;
  type: LiNodeType;
  /** Topic id for topics, the name for names, the entry key for entries. */
  label: string;
  /** Topics: tree level. */
  level?: 1 | 2 | 3;
  /** Topics and names: entries tagged with it. */
  count?: number;
  /** L2 topics: entries whose main topic it is (drawn in its flower). */
  own?: number;
  /** L2 topics, Topics view: the label sits above the flower (chosen at build time to avoid collisions). */
  labelAbove?: boolean;
  /** Topics, Map view: label offset from the node (collision-free placement computed at build time). */
  mapLabel?: [number, number];
  /** Entries: what kind of entry it is. */
  entryKind?: LiEntryKind;
  /** Entries: the media item shown as its card (absent = text post, drawn as a dot). */
  cover?: string;
  /** Entries: dot radius in the Timeline and Map (by reactions). */
  size?: number;
  /** Position in each view, in the graph's coordinate box; null = not shown in that view. */
  pos: Record<LiView, [number, number] | null>;
}

export interface LiGraph {
  width: number;
  height: number;
  nodes: LiGraphNode[];
  /** Entry to its topics (L2, L3) and names, and the topic tree itself (L3 to L2, L2 to L1): lit on hover. */
  links: [string, string][];
  /** Lines drawn at rest in each view (Topics: the topic tree, the fixed relations). */
  lines: Record<LiView, [string, string][]>;
  /** Topics view: each L1 area's region (centre, radius) for its outline and label. */
  regions: { id: string; x: number; y: number; r: number }[];
  timeline: {
    axisY: number;
    left: number;
    years: { year: string; x0: number; x1: number }[];
    /** One lane per L1 area. */
    lanes: { id: string; y: number }[];
  };
  map: { cx: number; cy: number; rings: { r: number; label: string }[] };
  /** Day the engagement numbers were read. */
  engagementAsOf?: string;
}
